"""Independent naive reference implementation (spec-literal) for cross-checks."""
import json

CAP = 20000


def monitor(op, p):
    """Return (m, delta) where delta(state, token) -> state; the truth state is m."""
    m = len(p)
    if op == 'match':
        fail = m + 1

        def delta(k, a):
            if k < m and a == p[k]:
                return k + 1
            return fail
        return m, delta
    if op == 'startswith':
        fail = m + 1

        def delta(k, a):
            if k < m and a == p[k]:
                return k + 1
            if k == m:
                return m
            return fail
        return m, delta

    def border_delta(k, a):
        cur = p[:k] + [a]
        best = 0
        top = min(k + 1, m)
        for j in range(top + 1):
            if p[:j] == cur[len(cur) - j:]:
                best = j
        return best

    if op == 'endswith':
        return m, border_delta

    def contains_delta(k, a):
        if k == m:
            return m
        return border_delta(k, a)

    return m, contains_delta


def collect_atoms(node, seen, keys):
    op = node['op']
    if op in ('true', 'false'):
        return
    if op in ('match', 'startswith', 'endswith', 'contains'):
        key = (op, tuple(node['path']))
        if key not in keys:
            keys.add(key)
            seen.append(key)
        return
    if op == 'not':
        collect_atoms(node['arg'], seen, keys)
        return
    for child in node['args']:
        collect_atoms(child, seen, keys)


def atoms_of(rules):
    seen = []
    keys = set()
    for _act, when in rules:
        collect_atoms(when, seen, keys)
    return seen


def evaluate(node, truth):
    op = node['op']
    if op == 'true':
        return True
    if op == 'false':
        return False
    if op in ('match', 'startswith', 'endswith', 'contains'):
        return truth[(op, tuple(node['path']))]
    if op == 'not':
        return not evaluate(node['arg'], truth)
    if op == 'and':
        return all([evaluate(c, truth) for c in node['args']])
    return any([evaluate(c, truth) for c in node['args']])


def atom_truth(op, p, path):
    mm = len(p)
    if op == 'match':
        return list(path) == list(p)
    if op == 'startswith':
        return len(path) >= mm and list(path[:mm]) == list(p)
    if op == 'endswith':
        return len(path) >= mm and list(path[len(path) - mm:]) == list(p)
    n = len(path)
    return any(list(path[i:i + mm]) == list(p) for i in range(n - mm + 1))


def predicate(request, path):
    """Direct path semantics of the whole bundle."""
    truth = {}
    for op, p in atoms_of([(None, w) for w in []]):
        pass
    for rule in request['rules']:
        for op, p in atoms_of([(rule['action'], rule['when'])]):
            if (op, p) not in truth:
                truth[(op, p)] = atom_truth(op, list(p), list(path))
    allow = False
    drop = False
    for rule in request['rules']:
        if evaluate(rule['when'], truth):
            if rule['action'] == 'allow':
                allow = True
            else:
                drop = True
    return allow and not drop


def build_product(atoms, services):
    mons = [(op, list(p)) + monitor(op, list(p)) for (op, p) in atoms]
    init = (0,) * len(mons)
    index = {init: 0}
    order = [init]
    i = 0
    while i < len(order):
        cur = order[i]
        i += 1
        for tok in services:
            nxt = tuple(mons[j][3](cur[j], tok) for j in range(len(mons)))
            if nxt not in index:
                if len(order) >= CAP:
                    return None, None
                index[nxt] = len(order)
                order.append(nxt)
    return order, mons


def refine(n, nsym, trans, acc):
    """Naive Moore minimization returning class_of."""
    cls = [1 if acc[s] else 0 for s in range(n)]
    if len(set(cls)) == 1:
        return cls[:]
    while True:
        sig = {}
        new = []
        for s in range(n):
            key = (cls[s], tuple([cls[trans[s][a]] for a in range(nsym)]))
            i = sig.get(key)
            if i is None:
                i = len(sig)
                sig[key] = i
            new.append(i)
        if len(sig) == len(set(cls)):
            return new
        cls = new


def compile_reference(request):
    services = list(request['services'])
    rules = list(request['rules'])
    queries = list(request['queries'])
    nsym = len(services)
    atoms = atoms_of(rules)
    order, mons = build_product(atoms, services)
    if order is None:
        return 'E_COMPLEXITY'
    n = len(order)
    acc = []
    for cur in order:
        truth = {}
        for j, (op, p, m, _d) in enumerate(mons):
            truth[(op, p)] = (cur[j] == m)
        allow = False
        drop = False
        for rule in rules:
            if evaluate(rule['when'], truth):
                if rule['action'] == 'allow':
                    allow = True
                else:
                    drop = True
        acc.append(bool(allow and not drop))
    trans = []
    for i, cur in enumerate(order):
        row = []
        for tok in services:
            nxt = tuple(mons[j][3](cur[j], tok) for j in range(len(mons)))
            row.append(order.index(nxt))
        trans.append(row)
    cls = refine(n, nsym, trans, acc)
    # quotient + canonical BFS numbering
    start_cls = cls[0]
    number = {start_cls: 0}
    seq = [start_cls]
    rep = {}
    for s in range(n):
        if cls[s] not in rep:
            rep[cls[s]] = s
    rows = []
    accept = []
    qi = 0
    while qi < len(seq):
        c = seq[qi]
        qi += 1
        s = rep[c]
        row = []
        for a in range(nsym):
            cc = cls[trans[s][a]]
            if cc not in number:
                number[cc] = len(seq)
                seq.append(cc)
            row.append(number[cc])
        rows.append(row)
        accept.append(acc[s])
    m = len(seq)
    # distance
    dist = [None] * m
    back = [[] for _ in range(m)]
    for s in range(m):
        for t in rows[s]:
            back[t].append(s)
    dq = [s for s in range(m) if accept[s]]
    for s in dq:
        dist[s] = 0
    h = 0
    while h < len(dq):
        s = dq[h]
        h += 1
        for p in back[s]:
            if dist[p] is None:
                dist[p] = dist[s] + 1
                dq.append(p)
    results = []
    for q in queries:
        s = 0
        for tok in q:
            s = rows[s][services.index(tok)]
        results.append({'state': s, 'allow': accept[s], 'distance': dist[s]})
    return {'ok': True,
            'dfa': {'start': 0, 'accept': accept, 'next': rows, 'distance': dist},
            'queries': results}
