class BitCounters(object):
    __slots__ = ('cnt',)

    def __init__(self):
        self.cnt = []

    def add(self, mask):
        cnt = self.cnt
        i = 0
        while mask:
            if i == len(cnt):
                cnt.append(mask)
                return
            carry = cnt[i] & mask
            cnt[i] ^= mask
            mask = carry
            i += 1

    def counts(self, n):
        res = [0] * n
        for j, b in enumerate(self.cnt):
            if not b:
                continue
            bit = 1 << j
            while b:
                low = b & -b
                res[low.bit_length() - 1] |= bit
                b ^= low
        return res


