    "STREAM": ("Z", "A"),
    "RESET_STREAM": ("Z", "A"),
    "STOP_SENDING": ("Z", "A"),
    "HANDSHAKE_DONE": (),
    "UNKNOWN": ("I", "H", "Z", "A"),
