    if self.state == "open":
        conn = {
            "state": "open",
            "code": None,
            "at_ms": None,
            "source": None,
            "peer_code": None,
            "last_activity_ms": self.last_activity,
        }
    else:
        conn = {
            "state": self.state,
            "code": self.code,
            "at_ms": self.at_ms,
            "source": self.source,
            "peer_code": self.peer_code,
            "last_activity_ms": self.last_activity,
        }
    return {
        "id": None,  # filled in by caller
        "packets": out_packets,
        "connection": conn,
        "keys": {
