                inside = counter[ident]
                counter[ident] = 0
                group = members[ident]
                if inside == len(group):
                    continue
                kept = []
                moved = []
                for q in group:
                    if marked[q]:
                        kept.append(q)
                    else:
                        moved.append(q)
                if len(moved) <= len(kept):
                    members[ident] = kept
                    fresh = moved
                else:
                    members[ident] = moved
                    fresh = kept
                new_id = len(members)
                members.append(fresh)
                counter.append(0)
                queued.append(False)
                for q in fresh:
