# --------------------------------------------------------------------------
def handle_line(raw):
    if len(raw) > LINE_BYTES:
        return ERR_LIMIT
    try:
        text = raw.decode('utf-8')
    except UnicodeDecodeError:
        return ERR_JSON
    if depth_exceeded(text):
