    S.records.append((ev, pk, status, reason, at, frame))


def terminate(S, state, code, at, src_ev, src_pk, src_fr, peer_code):
    if S.terminated:
        return
    S.terminated = True
    S.term = (state, code, at, (src_ev, src_pk, src_fr), peer_code)
    for e in S.pending:
        emit(S, e[1], e[2], 'dropped', 'CONNECTION_CLOSED', at, None)
    S.pending = []
    infl = S.inflight
    for e in infl[S.inflight_pos:]:
        emit(S, e[1], e[2], 'dropped', 'CONNECTION_CLOSED', at, None)
    S.inflight = []
    S.inflight_pos = 0


def rollback(S, undo, total_snap):
    for u in reversed(undo):
        k = u[0]
        if k == 0:
            del S.streams[u[1]]
        elif k == 1:
            st = S.streams[u[1]]
            st.highest = u[2]
            st.final_size = u[3]
            st.reset = u[4]
            st.stopped = u[5]
            st.ivs = u[6]
            d = st.delivered
            if len(d) > u[7]:
                del d[u[7]:]
        else:
            cs = S.crypto[u[1]]
            cs.highest = u[2]
            cs.ivs = u[3]
    S.total = total_snap


