import string
import sys
def top_words(path, n=10):
    counts = {}
    with open(path, encoding="utf-8") as f:
        for line in f:
            for w in line.split():
                w = w.strip(string.punctuation).lower()
                if w:
                    counts[w] = counts.get(w, 0) + 1
    return sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))[:n]
