def hierholzer(adj):
    """adj[u] = list of (eid, tgt) entries, each edge copy present exactly once.
    Returns list of edge ids forming an Eulerian circuit from start."""
    nc = len(adj)
    ptr = [0] * nc
    stack = [0]
    pops = []
    while stack:
        u = stack[-1]
        au = adj[u]
        if ptr[u] < len(au):
            en = au[ptr[u]]
            ptr[u] += 1
            stack.append(en[1])
        else:
