    order.append(start)
    qi = 0
    while qi < len(order):
        u = order[qi]
        qi += 1
        for eid, t in adj[u]:
            if par[t] == -2:
                par[t] = u
                pare[t] = eid
                order.append(t)
    reach = [False] * n
    for u in order:
        reach[u] = True
    safeflag = {}
    safe_ok = True
    for u in order:
        f = state_is_safe(states[u], expected, inp, P, R, D)
        safeflag[u] = f
        if not f:
