    else:
        par2 = [-2] * n
        par2[start] = -1
        pare2 = [0] * n
        q2 = [start]
        qi = 0
        found = None
        while qi < len(q2):
            u = q2[qi]
            qi += 1
            if not safeflag.get(u, True):
                found = u
                break
            for eid, t in adj[u]:
                if par2[t] == -2:
                    par2[t] = u
                    pare2[t] = eid
                    q2.append(t)
        path = []
