    tot = len(adj)
    enmask = [0] * tot
    mmask = [0] * tot
    ymask = [0] * tot
    for i in range(k):
        enm = enm_state[live[i]]
        enmask[i] = enm
        ymask[i] = (~enm) & DECL
    for j, (eid, b) in enumerate(m_nodes):
        nd = k + j
        ymask[nd] = b
        mmask[nd] = b
    allnodes = list(range(tot))
    comps = tarjan_subset(allnodes, set(allnodes), adj)
    members = [c for c in comps]
    work = list(range(len(members)))
    active = [True] * len(members)
    clean = []
    while work:
        c = work.pop()
        if not active[c]:
            continue
        mem = members[c]
        orE = 0
        orM = 0
        orY = 0
        for v in mem:
            orE |= enmask[v]
            orM |= mmask[v]
            orY |= ymask[v]
        rm = None
        for i in range(len(fair)):
            if fair[i][1] == "weak":
                if not ((orY >> i) & 1):
