        if rm is None:
            for i in range(len(fair)):
                if fair[i][1] == "strong":
                    if ((orE >> i) & 1) and not ((orM >> i) & 1):
                        bb = 1 << i
                        rm = [v for v in mem if enmask[v] & bb]
                        break
        if rm is None:
            clean.append(mem)
            active[c] = False
            continue
        active[c] = False
        if len(rm) == len(mem):
            continue
        rmset = set(rm)
        rem = [v for v in mem if v not in rmset]
        for nc in tarjan_subset(rem, set(rem), adj):
            members.append(nc)
            active.append(True)
            work.append(len(members) - 1)
    if not clean:
        return True, None
    adjl = [[] for _ in range(n)]
    for eid in range(len(edges)):
        s, lab, t = edges[eid]
        if liveb[s] and liveb[t]:
            adjl[s].append((eid, t))
    cand = []
    for mem in clean:
        cp = set()
        for v in mem:
            if v < k:
                cp.add(live[v])
        if cp:
            cand.append((len(cp), list(cp)))
    cand.sort()
    for _, cp in cand:
