                created.append(pid)
                st = "ok"
            else:
                st = "disabled"
        elif k == "retry":
            r = ev[1]
            ents = [e for e in buf if e is not None and len(e.ranks) == P and e.seq >= acked[r]]
            ents.sort(key=lambda e: e.seq)
            for e in ents:
                pid = new_packet("down", r, e.seq, list(e.sum))
                created.append(pid)
            st = "ok"
        elif k == "drop":
            if pending.pop(ev[1], None) is None:
                ev_status.append("missing")
                ev_created.append([])
                continue
            st = "ok"
        elif k == "duplicate":
            pkt = pending.get(ev[1])
            if pkt is None:
                ev_status.append("missing")
                ev_created.append([])
                continue
            created.append(new_packet(pkt[1], pkt[2], pkt[3], pkt[4]))
            st = "ok"
        else:
            pid = ev[1]
            pkt = pending.pop(pid, None)
            if pkt is None:
                ev_status.append("missing")
                ev_created.append([])
                continue
            kind = pkt[1]
            r = pkt[2]
