            if kind == "up":
                if floor <= q < floor + slotsn:
                    idx = q % slotsn
                    e = buf[idx]
                    if e is None or e.seq != q:
                        e = Ent(q)
                        buf[idx] = e
                    if r not in e.ranks:
                        vec = pkt[4]
                        s = e.sum
