                            s[i] += vec[i]
                        e.ranks.add(r)
                        became_full = len(e.ranks) == P
                    else:
                        became_full = False
                    n = up_next[r]
                    while True:
                        e2 = buf[n % slotsn]
                        if e2 is not None and e2.seq == n and r in e2.ranks:
                            n += 1
                        else:
                            break
                    up_next[r] = n
                    created.append(new_packet("uack", r, n, None))
                    if became_full:
                        s = list(e.sum)
                        for t in range(P):
                            created.append(new_packet("down", t, q, s))
                else:
                    created.append(new_packet("uack", r, up_next[r], None))
            elif kind == "uack":
                kk = pkt[3]
                if kk > sentv[r]:
                    sentv[r] = kk
            elif kind == "down":
                if q == len(received[r]):
                    received[r].append(pkt[4])
                created.append(new_packet("dack", r, len(received[r]), None))
            elif kind == "dack":
                kk = pkt[3]
                if kk > acked[r]:
                    acked[r] = kk
                    nf = min(acked)
