    if type(rng) is not list:
        raise Invalid()
    if len(rng) > 32:
        raise Invalid()
    for pair in rng:
        if type(pair) is not list or len(pair) != 2:
            raise Invalid()
        lo = pair[0]
        hi = pair[1]
        if not _is_int(lo) or not _is_int(hi):
            raise Invalid()
        if lo < 0 or hi > MAXN:
            raise Invalid()


