def _get_stream(self, sid):
    st = self.streams.get(sid)
    undo = self.undo
    if st is None:
        st = Stream(sid)
        self.streams[sid] = st
        undo.append((self, "newstream", sid))
    else:
        undo.append((st, "fields", (st.highest, st.final_size, st.reset, st.stopped)))
    return st

def _rollback(self):
    for entry in reversed(self.undo):
        kind = entry[1]
        if kind == "contig":
            entry[0].contig = entry[2]
        elif kind == "rt":
            entry[0].received_total = entry[2]
        elif kind == "fields":
            st = entry[0]
            st.highest, st.final_size, st.reset, st.stopped = entry[2]
        elif kind == "newstream":
            entry[0].streams.pop(entry[2], None)
        elif kind == "chighest":
            entry[0].highest = entry[2]
        else:  # chunk journal entry: (store, base, previous chunk or None)
            store = entry[0]
            base = entry[1]
            prev = entry[2]
            if prev is None:
                store.chunks.pop(base, None)
            else:
                store.chunks[base] = prev

