    def path_back(target):
        # target -> root edges
        if target == root:
            return []
        out = []
        cur = target
        while cur != root:
            eid = rpe[cur]
            out.append(eid)
            cur = rpn[cur]
        return out

    walk = []
    for (u, v, eid) in required:
        walk.extend(path_fwd(u))
        walk.append(eid)
        walk.extend(path_back(v))
    for w in witnesses:
        walk.extend(path_fwd(w))
        walk.extend(path_back(w))

    if not walk:
        walk = [-1]
    return root, walk

