class Store:
    """Sparse byte store keyed by fixed-size blocks.

    Each block is a [bytearray(BLOCK), present_mask] pair.
    """
    __slots__ = ('blocks',)

    def __init__(self):
        self.blocks = {}

    def conflicts(self, off, data):
        n = len(data)
        if n == 0:
            return False
        end = off + n
        first = off // BLOCK
        last = (end - 1) // BLOCK
        blocks = self.blocks
        for bi in range(first, last + 1):
            b = blocks.get(bi)
            if b is None:
                continue
            bstart = bi * BLOCK
            buf, mask = b
            lo = off - bstart
            if lo < 0:
                lo = 0
            hi = end - bstart
            if hi > BLOCK:
                hi = BLOCK
            m = (mask >> lo) & ((1 << (hi - lo)) - 1)
            base = bstart + lo - off  # index into data of block position lo
            while m:
                lsb = m & -m
                s = lsb.bit_length() - 1
                y = m + lsb
                run = m & (y - 1)
                k = run.bit_count()
                if buf[lo + s:lo + s + k] != data[base + s:base + s + k]:
                    return True
                m ^= run
        return False

    def store(self, off, data, j, keep_existing):
        n = len(data)
        if n == 0:
            return
        end = off + n
        first = off // BLOCK
        last = (end - 1) // BLOCK
        blocks = self.blocks
        for bi in range(first, last + 1):
            bstart = bi * BLOCK
            lo = off - bstart
            if lo < 0:
                lo = 0
            hi = end - bstart
            if hi > BLOCK:
                hi = BLOCK
            b = blocks.get(bi)
            if b is None:
                j.snap_block(self, bi, None, 0)
                b = [bytearray(BLOCK), 0]
                blocks[bi] = b
            else:
                j.snap_block(self, bi, b[0], b[1])
            buf = b[0]
            mask = b[1]
            if keep_existing:
                free = ((1 << (hi - lo)) - 1) & ~(mask >> lo)
                base = bstart + lo - off
                while free:
                    lsb = free & -free
                    s = lsb.bit_length() - 1
                    y = free + lsb
                    run = free & (y - 1)
                    k = run.bit_count()
                    buf[lo + s:lo + s + k] = data[base + s:base + s + k]
                    mask |= run << lo
                    free ^= run
            else:
                buf[lo:hi] = data[bstart + lo - off:bstart + hi - off]
                mask |= ((1 << (hi - lo)) - 1) << lo
            b[1] = mask

    def prefix(self):
        out = bytearray()
        bi = 0
        blocks = self.blocks
        while True:
            b = blocks.get(bi)
            if b is None:
                break
            buf, mask = b
            fz = ~mask & BMASK
            if fz:
                fz = (fz & -fz).bit_length() - 1
            else:
                fz = BLOCK
            out += buf[:fz]
            if fz < BLOCK:
                break
            bi += 1
        return bytes(out)


class Journal:
    __slots__ = ('items', 'seen', 'st')

    def __init__(self, st):
        self.items = []
        self.seen = set()
        self.st = st

    def snap_block(self, store, bi, data, mask):
        key = (store, bi)
        if key in self.seen:
            return
        self.seen.add(key)
        self.items.append((0, store, bi, data, mask))

    def snap_stream(self, s):
        if s in self.seen:
            return
        self.seen.add(s)
        self.items.append((1, s, s.highest, s.final_size, s.reset, s.stopped))

    def snap_total(self):
        if 'T' in self.seen:
            return
        self.seen.add('T')
        self.items.append((2, self.st.received_total))

    def new_stream(self, sid):
        self.items.append((3, sid))

    def rollback(self):
        st = self.st
        for it in reversed(self.items):
            k = it[0]
            if k == 0:
                store = it[1]
                bi = it[2]
                data = it[3]
                if data is None:
                    store.blocks.pop(bi, None)
                else:
                    b = store.blocks.get(bi)
                    if b is None:
                        store.blocks[bi] = [bytearray(data), it[4]]
                    else:
                        b[0][:] = data
                        b[1] = it[4]
            elif k == 1:
                s = it[1]
                s.highest = it[2]
                s.final_size = it[3]
                s.reset = it[4]
                s.stopped = it[5]
            elif k == 2:
                st.received_total = it[1]
            else:
                st.streams.pop(it[1], None)


class Stream:
    __slots__ = ('sid', 'highest', 'final_size', 'reset', 'stopped', 'store')

