def parse_host(h):
    if not h or len(h) > 253:
        return None
    labels = h.split(".")
    if len(labels) < 2:
        return None
    last = len(labels) - 1
    for i, lab in enumerate(labels):
        n = len(lab)
        if n < 1 or n > 63:
            return None
        for c in lab:
            if c not in LDH:
                return None
        if lab[0] == "-" or lab[-1] == "-":
            return None
        if i == last and lab[0] not in ASCII_LETTERS:
            return None
    return h.lower()


