    for c in p:
        if c not in DIGITS:
            return None
    v = int(p)
    if v < 1 or v > 65535:
        return None
    return str(v)


def parse_sip(s):
    """Canonical form of a SIP/SIPS URI, or None."""
    if s[:5].lower() == "sips:":
        sch = "sips"
        rest = s[5:]
    elif s[:4].lower() == "sip:":
        sch = "sip"
        rest = s[4:]
    else:
        return None
    at = rest.find("@")
    if at < 0:
        return None
    user_raw = rest[:at]
    hp = rest[at + 1:]
    if "@" in hp:
        return None
    out = []
    i = 0
    n = len(user_raw)
    while i < n:
        c = user_raw[i]
        if c == "%":
            if i + 2 >= n:
                return None
            a = user_raw[i + 1]
            b = user_raw[i + 2]
            if a not in HEXDIG or b not in HEXDIG:
                return None
            ch = chr(int(user_raw[i + 1:i + 3], 16))
            if ch not in USER_CHARS:
                return None
            out.append(ch)
            i += 3
        elif c in USER_CHARS:
            out.append(c)
            i += 1
        else:
            return None
    if not (1 <= len(out) <= 64):
        return None
    user = "".join(out)
    ci = hp.find(":")
    if ci < 0:
        host_raw, port = hp, ""
    else:
        if hp.find(":", ci + 1) >= 0:
            return None
        host_raw = hp[:ci]
        port = parse_port(hp[ci + 1:])
        if port is None:
            return None
        port = ":" + port
    host = parse_host(host_raw)
    if host is None:
        return None
    return sch + ":" + user + "@" + host + port


def parse_tel(s):
    body = s[4:]
    if not body.startswith("+"):
        return None
    digits = []
    for c in body[1:]:
        if c in DIGITS:
            digits.append(c)
        elif c == "-" or c == "." or c == "(" or c == ")":
            continue
        else:
            return None
    nd = len(digits)
    if nd < 3 or nd > 15:
        return None
    if digits[0] == "0":
        return None
    return "tel:+" + "".join(digits)


def parse_uri(s):
    """Canonical form of a SIP/SIPS/tel URI, or None."""
    if s[:4].lower() == "tel:":
        return parse_tel(s)
    if s[:5].lower() == "sips:" or s[:4].lower() == "sip:":
        return parse_sip(s)
    return None


def uri_kind(canon):
    """'sip' for SIP/SIPS canonical URIs, 'tel' for telephone URIs."""
    if canon[:4] == "tel:":
        return "tel"
    return "sip"


# --------------------------------------------------------------------------
# address (display-name / angle-addr / bare URI) scanning
# --------------------------------------------------------------------------
def scan_quoted(s, i):
    """s[i] == '"'; return index just past the closing quote."""
    n = len(s)
    i += 1

        if i >= n:
            raise FieldError("unterminated quoted display name")
        c = s[i]
        if c == "\\":
            if i + 1 < n:
                nxt = s[i + 1]
                if nxt == "\t" or ("!" <= nxt <= "~"):
                    i += 2
                    continue
            raise FieldError("bad escape in quoted display name")
        if c == '"':
            return i + 1
        if c == "\t" or (" " <= c <= "~"):
            i += 1
            continue
        raise FieldError("bad byte in quoted display name")


def check_unquoted_dn(dn):
    got = dn.split()
    if not got:
        raise FieldError("empty display name")
    for t in got:
        if TOKEN_RE.fullmatch(t) is None:
            raise FieldError("bad unquoted display name token")


def scan_addr(s, terms):
    """Scan one address at the start of ``s``.

    ``terms`` are characters that terminate a bare URI (not consumed).
    Returns ``(uri_text, rest_text)``; raises FieldError on bad syntax.
    """
    n = len(s)
    i = 0
    while i < n and (s[i] == " " or s[i] == "\t"):
        i += 1
    if i >= n:
        raise FieldError("empty address")
    c = s[i]
    if c == '"':
        i = scan_quoted(s, i)
        while i < n and (s[i] == " " or s[i] == "\t"):
            i += 1
        if i >= n or s[i] != "<":
            raise FieldError("junk after quoted display name")
        lt = i
    elif c == "<":
        lt = i
    else:
        limit = n
        for ch in terms:
            p = s.find(ch, i)
            if p >= 0 and p < limit:
                limit = p
        p = s.find("<", i)
        if p >= 0 and p < limit:
            dn = s[i:p].rstrip(" \t")
            if dn:
                check_unquoted_dn(dn)
            lt = p
        else:
            return s[i:limit].rstrip(" \t"), s[limit:]
    gt = s.find(">", lt + 1)
    if gt < 0:
        raise FieldError("unmatched angle bracket")
    inner = s[lt + 1:gt]
    if " " in inner or "\t" in inner:
        raise FieldError("whitespace inside angle brackets")
    return inner, s[gt + 1:]

