        'audits': audits,
        'diagnostic': {
            'equivalence': equivalence,
            'basis': basis,
            'cost': cost,
            'count': count,
        },
    }


def main():
    raw = sys.stdin.buffer.read()
    try:
        result = analyze(raw)
    except Invalid:
        result = {'error': 'invalid-input'}
    except Exception:
        result = {'error': 'invalid-input'}
    sys.stdout.write(json.dumps(result, separators=(',', ':')) + '\n')
    return 0


if __name__ == '__main__':
    sys.exit(main())

