# Boolean simplification (exact; used only to pick the product components)
# --------------------------------------------------------------------------

def simplify(node):
    tag = node[0]
    if tag == 'const':
        return node
    if tag == 'not':
        inner = simplify(node[1])
        if inner[0] == 'const':
            return ('const', not inner[1])
        return ('not', inner)
    if tag == 'and':
        kept = []
        for arg in node[1]:
            red = simplify(arg)
            if red[0] == 'const':
                if not red[1]:
                    return ('const', False)
                continue
            kept.append(red)
        if not kept:
            return ('const', True)
        if len(kept) == 1:
            return kept[0]
        return ('and', kept)
    if tag == 'or':
        kept = []
        for arg in node[1]:
            red = simplify(arg)
            if red[0] == 'const':
                if red[1]:
                    return ('const', True)
                continue
            kept.append(red)
        if not kept:
            return ('const', False)
        if len(kept) == 1:
            return kept[0]
        return ('or', kept)
    return node


def collect_atoms(node, out):
    stack = [node]
    while stack:
        cur = stack.pop()
        tag = cur[0]
        if tag == 'and' or tag == 'or':
            stack.extend(cur[1])
        elif tag == 'not':
            stack.append(cur[1])
        elif tag == 'const':
            pass
        else:
            if cur not in out:
                out[cur] = None


