def make_monitor(op, path, tokens):
    m = len(path)
    n = len(tokens)
    if op == 'match':
        size = m + 2
        dead = m + 1
        table = [[dead] * n for _ in range(size)]
        for k in range(m):
            want = path[k]
            row = table[k]
            for t in range(n):
                if tokens[t] == want:
                    row[t] = k + 1
        return table, m
    if op == 'startswith':
        size = m + 2
        dead = m + 1
        table = [[dead] * n for _ in range(size)]
        for k in range(m):
            want = path[k]
            row = table[k]
            for t in range(n):
                if tokens[t] == want:
                    row[t] = k + 1
        table[m] = [m] * n
        return table, m
    if op == 'endswith' or op == 'contains':
        size = m + 1
        table = []
        for k in range(size):
            if op == 'contains' and k == m:
                table.append([m] * n)
                continue
            base = path[:k]
            limit = k + 1
            if limit > m:
                limit = m
            row = []
            for t in range(n):
                seq = base + [tokens[t]]
                j = limit
                while j > 0:
                    if seq[k + 1 - j:] == path[:j]:
                        break
                    j -= 1
                row.append(j)
            table.append(row)
        return table, m
    raise AssertionError('unknown atom op')


def product_reachable_count(tables, alpha):
    """Distinct reachable monitor-product tuples; -1 once over the cap."""
    k = len(tables)
    if k == 0:
        return 1
    seen = {tuple([0] * k)}
    count = 1
    frontier = list(seen)
    tokens = range(alpha)
    while frontier:
        nxt_frontier = []
        for state in frontier:
            rows = [tables[j][state[j]] for j in range(k)]
            for t in tokens:
                nxt = tuple([row[t] for row in rows])
                if nxt not in seen:
                    seen.add(nxt)
                    count += 1
                    if count > MAX_PRODUCT:
                        return -1
                    nxt_frontier.append(nxt)
        frontier = nxt_frontier
    return count


