def build_product(tables, truths, alpha, accept_of_mask):
    k = len(tables)
    start = tuple([0] * k)
    index = {start: 0}
    states = [start]
    accept = [accept_of_mask(0)]
    trans = []
    tokens = range(alpha)
    i = 0
    while i < len(states):
        state = states[i]
        rows = [tables[j][state[j]] for j in range(k)]
        row = []
        for t in tokens:
            nxt = tuple([r[t] for r in rows])
            j = index.get(nxt)
            if j is None:
                j = len(states)
                index[nxt] = j
                states.append(nxt)
