def process(raw):
    try:
        if len(raw) > MAX_LINE_BYTES:
            return E_LIMIT
        try:
            text = raw.decode('utf-8')
        except UnicodeDecodeError:
            return E_JSON
        if not depth_ok(text):
            return E_LIMIT
        try:
            doc = _json_load(text)
        except CodedError:
            return E_JSON
        except (ValueError, RecursionError):
            return E_JSON

        check_scalars(doc)
        services, rule_asts, queries = validate_bundle(doc)
        all_atoms = check_limits(services, rule_asts, queries)

        tables = [mon[0] for mon in
                  (make_monitor(op, path, services)
                   for (op, path) in all_atoms)]
        if product_reachable_count(tables, len(services)) < 0:
            return E_COMPLEXITY

        return compile_bundle(services, rule_asts, queries)
    except CodedError as err:
        code = err.code
        if code == 'E_JSON':
            return E_JSON
        if code == 'E_LIMIT':
            return E_LIMIT
        if code == 'E_SCHEMA':
            return E_SCHEMA
        return E_COMPLEXITY
    except Exception:
        # never let one line take the whole stream down
        traceback.print_exc(file=sys.stderr)
        return E_JSON


def main():
    data = sys.stdin.buffer.read()
    lines = data.split(b'\n')
    if lines and not lines[-1]:
        lines.pop()
    out = []
    for raw in lines:
        out.append(process(raw))
    if out:
        sys.stdout.write('\n'.join(out) + '\n')
    sys.stdout.flush()


if __name__ == '__main__':
    main()

