def collect_atoms(node, out):
    stack = [node]
    while stack:
        cur = stack.pop()
        tag = cur[0]
        if tag == 'and' or tag == 'or':
            stack.extend(cur[1])
        elif tag == 'not':
            stack.append(cur[1])
        elif tag == 'const':
            pass
        else:
            if cur not in out:
                out[cur] = None


# --------------------------------------------------------------------------
# atomic monitors (exactly as the contract defines them)
# --------------------------------------------------------------------------

def make_monitor(op, path, tokens):
    path = list(path)
    m = len(path)
    n = len(tokens)
    if op == 'match':
        size = m + 2
        dead = m + 1
        table = [[dead] * n for _ in range(size)]
        for k in range(m):
            want = path[k]
            row = table[k]
            for t in range(n):
                if tokens[t] == want:
                    row[t] = k + 1
        return table, m
    if op == 'startswith':
        size = m + 2
        dead = m + 1
        table = [[dead] * n for _ in range(size)]
        for k in range(m):
            want = path[k]
            row = table[k]
            for t in range(n):
                if tokens[t] == want:
                    row[t] = k + 1
        table[m] = [m] * n
        return table, m
    if op == 'endswith' or op == 'contains':
        size = m + 1
        table = []
        for k in range(size):
            if op == 'contains' and k == m:
                table.append([m] * n)
                continue
            base = path[:k]
            limit = k + 1
            if limit > m:
                limit = m
            row = []
            for t in range(n):
                seq = base + [tokens[t]]
                j = limit
                while j > 0:
                    if seq[k + 1 - j:] == path[:j]:
                        break
                    j -= 1
                row.append(j)
            table.append(row)
        return table, m
    raise AssertionError('unknown atom op')

