def hopcroft(n, A, trans, accept):
    if n <= 1:
        blocks = {0: set(range(n))}
        block_of = [0] * n
        return blocks, block_of

    # predecessor lists
    pred = [[[] for _ in range(n)] for _ in range(A)]
    for s in range(n):
        row = trans[s]
        for c in range(A):
            pred[c][row[c]].append(s)

    blocks = {}
    block_of = [0] * n
    nxt = [0]

    def new_block(S):
        bid = nxt[0]
        nxt[0] += 1
        blocks[bid] = S
        for s in S:
            block_of[s] = bid
        return bid

    acc = set(s for s in range(n) if accept[s])
    non = set(s for s in range(n) if not accept[s])
    if acc:
        new_block(acc)
    if non:
        new_block(non)

    Wd = deque()
    inW = set()

