MASK128 = (1 << 128) - 1

# ---------------------------------------------------------------- addresses --

_HEX = {}
for _i, _c in enumerate('0123456789abcdef'):
    _HEX[_c] = _i
for _i, _c in enumerate('ABCDEF'):
    _HEX[_c] = _i


def parse_addr(s):
    """Parse an IPv6 address in pure-hex colon notation.  Returns int or None."""
    n = len(s)
    if n == 0 or n > 39:
        return None
    i = s.find('::')
    if i >= 0:
        if s.find('::', i + 1) >= 0:
            return None
        left = s[:i]
        right = s[i + 2:]
        lg = left.split(':') if left else ()
        rg = right.split(':') if right else ()
        tail = 8 - len(lg) - len(rg)
        if tail < 1:
            return None
        val = 0
        for g in lg:
            if not g or len(g) > 4:
                return None
            v = 0
            for ch in g:
                d = _HEX.get(ch)
                if d is None:
                    return None
                v = (v << 4) | d
            val = (val << 16) | v
        val <<= 16 * tail
        for g in rg:
            if not g or len(g) > 4:
                return None
            v = 0
            for ch in g:
                d = _HEX.get(ch)
                if d is None:
                    return None
                v = (v << 4) | d
            val = (val << 16) | v
        return val
    parts = s.split(':')
    if len(parts) != 8:
        return None
    val = 0
    for g in parts:
        if not g or len(g) > 4:
            return None
        v = 0
        for ch in g:
            d = _HEX.get(ch)
            if d is None:
                return None
            v = (v << 4) | d
        val = (val << 16) | v
    return val


def fmt_addr(v):
    """Canonical pure-hex rendering of a 128-bit address."""
    g = [(v >> sh) & 0xffff for sh in (112, 96, 80, 64, 48, 32, 16, 0)]
    bi = -1
    bl = 1
    i = 0
    while i < 8:
        if g[i] == 0:
            j = i + 1
            while j < 8 and g[j] == 0:
                j += 1
            if j - i > bl:
                bl = j - i
                bi = i
            i = j
        else:
            i += 1
    if bi < 0:
        return ':'.join('%x' % x for x in g)
    left = ':'.join('%x' % x for x in g[:bi])
    right = ':'.join('%x' % x for x in g[bi + bl:])
    if left and right:
        return left + '::' + right
    if left:
        return left + '::'
    if right:
        return '::' + right
    return '::'


def parse_prefix(s):
    """Parse 'addr/len'.  Returns (net, len) or None."""
    if not isinstance(s, str):
        return None
    i = s.find('/')
    if i < 0:
        return None
    if s.find('/', i + 1) >= 0:
        return None
    a = parse_addr(s[:i])
    if a is None:
        return None
    ls = s[i + 1:]
    if not ls or len(ls) > 3:
        return None
    for ch in ls:
        if ch < '0' or ch > '9':
            return None
    if ls[0] == '0' and len(ls) > 1:
        return None
    plen = int(ls)
    if plen > 128:
        return None
    mask = ((1 << plen) - 1) << (128 - plen)
    if a & ~mask:
        return None
    return (a, plen)


def fmt_prefix(net, plen):
    return fmt_addr(net) + '/' + str(plen)

