from fractions import Fraction
def mine(z, s):
    d = 1 << s
    if d == 1:
        return z
    h = d >> 1
    if z >= 0:
        return (z + h) // d
    return -((h - z) // d)
def ref(z, s):
    # round half away from zero using Fraction
    q = Fraction(z, 1 << s)
    if q >= 0:
        # floor(q + 1/2)
        return int((q + Fraction(1,2)).__floor__())
    else:
        return -int(((-q) + Fraction(1,2)).__floor__())
