        guard checks below make the result depend only on satisfiability
        answers, never on the relaxation being solved correctly:  any value
        proved attainable outside the candidate interval widens it back to the
        demand box, and the binary search then proves the exact extremum.
        """
        key = (s, coef)
        hit = self.intcache.get(key)
        if hit is not None:
            return hit
        slo, shi = self.mdl.static_bounds(s, coef)
        if slo == shi:
            self.intcache[key] = (slo, slo)
            return (slo, slo)
        lmin, lmax = self.lp_pair(s, coef)
        relaxed = lmin is not None and lmax is not None
        if relaxed:
            a = max(slo, ceil_frac(lmin))
            b = min(shi, floor_frac(lmax))
            if a > b:
                a, b, relaxed = slo, shi, False
        else:
            a, b = slo, shi
        if self.out_of_time():
            # Safety valve: keep valid (possibly unattained) bounds.
            sys.stderr.write('deadline hit: loose bounds for objective\n')
            self.intcache[key] = (a, b)
            return (a, b)
        e = self.iv.expr(s, coef)
        if relaxed:
            if a > slo and self.check([e <= a - 1]):
                a = slo          # relaxation lower bound was not sound
            if b < shi and self.check([e >= b + 1]):
                b = shi          # relaxation upper bound was not sound
        lo = self.refine(s, coef, a, b, False)
        hi = self.refine(s, coef, a, b, True)
        self.intcache[key] = (lo, hi)
        return (lo, hi)

    # -- results ---------------------------------------------------------
    def witness_from_model(self, m):
        C, S = self.mdl.C, self.mdl.S
        q = [[m.evaluate(self.iv.q[s][c], model_completion=True)
              for c in range(C)] for s in range(S)]
        vals = []
        for s in range(S):
            row = []
            for c in range(C):
                v = q[s][c]
                if z3.is_int_value(v):
                    row.append(v.as_long())
                else:
                    f = rat_of(v)
                    if f is None or f.denominator != 1:
                        raise EngineError('non integer demand in model')
                    row.append(int(f))
            vals.append(row)
        return vals

    def evaluate(self, q):
        """Scaled link loads and the actually violated domain set."""
        mdl = self.mdl
        links = []
        for s in range(mdl.S):
            row = []
            for ei in range(mdl.E):
                coef = mdl.link_coef[ei]
                row.append(sum(cf * q[s][c] for c, cf in enumerate(coef) if cf))
            links.append(row)
        faults = []
        for d in mdl.observed_domains:
            for (si, coef, lo, hi) in mdl.dom_obs[d]:
                v = sum(cf * q[si][c] for c, cf in enumerate(coef) if cf)
                if v < lo or v > hi:
                    faults.append(d)
                    break
        return links, faults


