    if s.count('::') > 1:
        raise Invalid()
    if '::' in s:
        left, right = s.split('::')
        lg = left.split(':') if left != '' else []
        rg = right.split(':') if right != '' else []
        groups = lg + rg
        if len(groups) >= 8:
            raise Invalid()
        vals = []
        for g in groups:
            if g == '' or len(g) > 4:
                raise Invalid()
            for ch in g:
                if ch not in HEXCHARS:
                    raise Invalid()
            vals.append(int(g, 16))
        zeros = 8 - len(vals)
        allvals = vals[:len(lg)] + [0] * zeros + vals[len(lg):]
        if len(allvals) != 8:
            raise Invalid()
    else:
        parts = s.split(':')
        if len(parts) != 8:
            raise Invalid()
        allvals = []
        for g in parts:
            if g == '' or len(g) > 4:
                raise Invalid()
            for ch in g:
                if ch not in HEXCHARS:
                    raise Invalid()
            allvals.append(int(g, 16))
    val = 0
